final class StraySafe_Payment_Gateway_Manager {
  private $providers = [];
  public static function default_capabilities() { return ['subscriptions'=>false,'variable_subscriptions'=>false,'variable_one_off_amounts'=>false,'apple_pay'=>false,'google_pay'=>false,'gift_aid'=>false,'fee_recovery'=>false,'saved_cards'=>false,'embedded_checkout'=>false]; }
  public function __construct() { foreach ([new StraySafe_Stripe_Payment_Provider(), new StraySafe_PayPal_Payment_Provider(), new StraySafe_Square_Payment_Provider(), new StraySafe_GoCardless_Payment_Provider(), new StraySafe_SumUp_Payment_Provider()] as $provider) $this->register($provider); do_action('straysafe_payments_register_providers', $this); }
  public function register(StraySafe_Payment_Provider_Interface $provider) { $this->providers[$provider->get_id()] = $provider; }
  public function all() { return apply_filters('straysafe_payments_providers', $this->providers); }
  public function get($id) { $all = $this->all(); return $all[$id] ?? reset($all); }
  public function create_checkout(array $request, array $settings) { $provider = $this->get($settings['active_provider'] ?? 'stripe'); return $provider ? $provider->create_checkout($request, $settings['provider_settings'][$provider->get_id()] ?? []) : new WP_Error('no_provider', __('No payment provider is available.', 'straysafe-ui-suite')); }
}

function registerPaymentProvider(StraySafe_Payment_Provider_Interface $provider) { StraySafe_Payments_Module::gateway_manager()->register($provider); }

final class StraySafe_Payments_Module {
  const OPTION_KEY = 'straysafe_payments_settings_v1';
  const AUDIT_KEY = 'straysafe_payments_audit_v1';
  public static function init() { add_action('admin_menu',[__CLASS__,'admin_menu']); add_action('admin_post_straysafe_payments_save',[__CLASS__,'handle_save']); add_action('wp_ajax_straysafe_payments_checkout',[__CLASS__,'handle_checkout']); add_action('wp_ajax_nopriv_straysafe_payments_checkout',[__CLASS__,'handle_checkout']); add_shortcode('donation_widget',[__CLASS__,'render_shortcode']); add_action('init',[__CLASS__,'register_block']); add_action('wp_enqueue_scripts',[__CLASS__,'enqueue_frontend_assets']); }
  public static function gateway_manager() { static $m; if (!$m) $m = new StraySafe_Payment_Gateway_Manager(); return $m; }
  public static function defaults() { return ['active_provider'=>'stripe','provider_settings'=>[],'general'=>['enabled'=>1,'default_type'=>'one_off','currency'=>'GBP','success_url'=>home_url('/thank-you/'),'cancel_url'=>home_url('/'),'button_text'=>'Continue','thank_you_message'=>'Thank you for your support.','enable_campaigns'=>1,'title'=>'Support our work','subtitle'=>'Choose an amount that works for you','intro_text'=>'','learn_more_url'=>''],'one_off'=>['enabled'=>1,'allow_custom'=>1,'min'=>1,'max'=>10000,'default'=>5,'presets'=>[['amount'=>'3','description'=>'Makes a small contribution'],['amount'=>'5','description'=>'Supports essential work'],['amount'=>'10','description'=>'Helps fund ongoing services'],['amount'=>'17.50','description'=>'Creates meaningful impact']]],'recurring'=>['enabled'=>1,'allow_custom'=>1,'min'=>1,'max'=>1000,'default'=>5,'presets'=>[['amount'=>'3','description'=>'Provides steady monthly support'],['amount'=>'5','description'=>'Funds reliable monthly help'],['amount'=>'10','description'=>'Sustains ongoing work'],['amount'=>'17.50','description'=>'Creates lasting impact']]],'campaigns'=>[],'appearance'=>['primary'=>'#401268','background'=>'#ffffff','text'=>'#1f2937','radius'=>16,'shadow'=>1,'mode'=>'light','show_logo'=>0]]; }
  public static function settings() { return wp_parse_args(get_option(self::OPTION_KEY, []), self::defaults()); }
  public static function admin_menu() { add_menu_page('Payments','Payments','manage_options','straysafe-payments',[__CLASS__,'render_admin_page'],'dashicons-money-alt',56); }
  public static function enqueue_frontend_assets() { wp_enqueue_style('straysafe-payments', STRAYSAFE_SUITE_URL.'assets/css/payments.css', [], STRAYSAFE_SUITE_VERSION); wp_enqueue_script('straysafe-payments', STRAYSAFE_SUITE_URL.'assets/js/payments.js', [], STRAYSAFE_SUITE_VERSION, true); wp_localize_script('straysafe-payments','StraySafePayments',['ajaxUrl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('straysafe_payments_checkout')]); }
  public static function register_block() { if (function_exists('register_block_type')) register_block_type('asm-suite/donation-widget',['api_version'=>2,'title'=>'Payments Donation Widget','category'=>'widgets','attributes'=>['campaign'=>['type'=>'string'],'default'=>['type'=>'string'],'theme'=>['type'=>'string']],'render_callback'=>function($a=[]){ return self::render_shortcode($a); }]); }
  public static function handle_save() {
    if (!current_user_can('manage_options')) wp_die('Permission denied.'); check_admin_referer('straysafe_payments_save');
    $input = isset($_POST['payments']) && is_array($_POST['payments']) ? wp_unslash($_POST['payments']) : []; $clean = self::settings();
    $providers = self::gateway_manager()->all(); $active = sanitize_key($input['active_provider'] ?? $clean['active_provider']); $clean['active_provider'] = isset($providers[$active]) ? $active : 'stripe';
    foreach ($providers as $id=>$provider) foreach ($provider->get_configuration_fields() as $key=>$field) { $v = $input['provider_settings'][$id][$key] ?? ($clean['provider_settings'][$id][$key] ?? ''); $clean['provider_settings'][$id][$key] = $field['type']==='checkbox' ? (!empty($v)?1:0) : sanitize_text_field((string)$v); }
    $g=$input['general']??[]; foreach(['title','subtitle','intro_text','button_text','thank_you_message'] as $k) $clean['general'][$k]=sanitize_text_field($g[$k]??$clean['general'][$k]); foreach(['success_url','cancel_url','learn_more_url'] as $k) $clean['general'][$k]=esc_url_raw($g[$k]??$clean['general'][$k]); $clean['general']['enabled']=!empty($g['enabled'])?1:0; $clean['general']['enable_campaigns']=!empty($g['enable_campaigns'])?1:0; $clean['general']['currency']=preg_replace('/[^A-Z]/','',strtoupper($g['currency']??$clean['general']['currency'])) ?: 'GBP'; $clean['general']['default_type']=in_array(($g['default_type']??'one_off'),['one_off','recurring'],true)?$g['default_type']:'one_off';
    foreach(['one_off','recurring'] as $section){ $in=$input[$section]??[]; $clean[$section]['enabled']=!empty($in['enabled'])?1:0; $clean[$section]['allow_custom']=!empty($in['allow_custom'])?1:0; foreach(['min','max','default'] as $k) $clean[$section][$k]=max(0,(float)($in[$k]??$clean[$section][$k])); $clean[$section]['presets']=[]; foreach(($in['presets']??[]) as $row){ if (!is_array($row) || !is_numeric($row['amount']??'')) continue; $clean[$section]['presets'][]=['amount'=>(string)max(0,(float)$row['amount']),'description'=>sanitize_text_field($row['description']??''),'icon'=>sanitize_text_field($row['icon']??''),'colour'=>sanitize_hex_color($row['colour']??'') ?: '','campaign'=>sanitize_key($row['campaign']??'')]; }}
    $a=$input['appearance']??[]; foreach(['primary','background','text'] as $k) $clean['appearance'][$k]=sanitize_hex_color($a[$k]??$clean['appearance'][$k]) ?: $clean['appearance'][$k]; $clean['appearance']['radius']=max(0,min(48,(int)($a['radius']??16))); $clean['appearance']['shadow']=!empty($a['shadow'])?1:0; $clean['appearance']['mode']=($a['mode']??'light')==='dark'?'dark':'light'; $clean['appearance']['show_logo']=!empty($a['show_logo'])?1:0;
    update_option(self::OPTION_KEY, apply_filters('straysafe_payments_sanitized_settings',$clean,$input), false); self::audit('settings_saved',['provider'=>$clean['active_provider']]); wp_safe_redirect(admin_url('admin.php?page=straysafe-payments&updated=1')); exit;
  }
  private static function audit($event,$data=[]) { $log=get_option(self::AUDIT_KEY,[]); $log[]=array_merge(['time'=>current_time('mysql'),'event'=>sanitize_key($event),'user'=>get_current_user_id()],['data'=>$data]); update_option(self::AUDIT_KEY,array_slice($log,-100),false); }
  public static function handle_checkout() { check_ajax_referer('straysafe_payments_checkout','nonce'); $s=self::settings(); $type=sanitize_key($_POST['type']??'one_off'); $amount=(float)($_POST['amount']??0); $section=$type==='recurring'?'recurring':'one_off'; if (empty($s['general']['enabled'])||empty($s[$section]['enabled'])||$amount<(float)$s[$section]['min']||$amount>(float)$s[$section]['max']) wp_send_json_error(['message'=>'Please enter a valid amount.'],400); $result=self::gateway_manager()->create_checkout(['amount'=>$amount,'type'=>$type,'currency'=>$s['general']['currency'],'success_url'=>$s['general']['success_url'],'cancel_url'=>$s['general']['cancel_url']],$s); if (is_wp_error($result)) wp_send_json_error(['message'=>$result->get_error_message()],400); wp_send_json_success($result); }
  public static function render_shortcode($atts=[]) { $s=apply_filters('straysafe_payments_widget_settings', self::settings(), $atts); if (empty($s['general']['enabled'])) return ''; $p=self::gateway_manager()->get($s['active_provider']); $caps=$p?$p->get_capabilities():[]; $default=($atts['default']??$s['general']['default_type'])==='monthly'?'recurring':$s['general']['default_type']; ob_start(); ?>
<section class="ss-payments-widget ss-payments-<?php echo esc_attr($s['appearance']['mode']); ?>" style="--ssp-primary:<?php echo esc_attr($s['appearance']['primary']); ?>;--ssp-bg:<?php echo esc_attr($s['appearance']['background']); ?>;--ssp-text:<?php echo esc_attr($s['appearance']['text']); ?>;--ssp-radius:<?php echo (int)$s['appearance']['radius']; ?>px" data-currency="<?php echo esc_attr($s['general']['currency']); ?>" data-default-type="<?php echo esc_attr($default); ?>" data-caps="<?php echo esc_attr(wp_json_encode($caps)); ?>" aria-label="Payment widget">
  <h2><?php echo esc_html($s['general']['title']); ?></h2><p class="ss-payments-subtitle"><?php echo esc_html($s['general']['subtitle']); ?></p><?php if($s['general']['intro_text']) echo '<p>'.esc_html($s['general']['intro_text']).'</p>'; if($s['general']['learn_more_url']) echo '<a class="ss-payments-learn" href="'.esc_url($s['general']['learn_more_url']).'">'.esc_html__('Learn more','straysafe-ui-suite').'</a>'; ?>
  <div class="ss-payments-types" role="tablist"><button type="button" data-type="one_off">One-off</button><?php if(!empty($caps['subscriptions'])):?><button type="button" data-type="recurring">Monthly ❤️</button><?php endif; ?></div>
  <?php foreach(['one_off','recurring'] as $section): if(empty($s[$section]['enabled'])) continue; ?><div class="ss-payments-amounts" data-section="<?php echo esc_attr($section); ?>"><?php foreach($s[$section]['presets'] as $preset): ?><button type="button" data-amount="<?php echo esc_attr($preset['amount']); ?>" data-description="<?php echo esc_attr($preset['description']); ?>"><?php echo esc_html(self::money($preset['amount'],$s['general']['currency'])); ?></button><?php endforeach; if(!empty($s[$section]['allow_custom']) && ($section==='one_off' || !empty($caps['variable_subscriptions']))): ?><label><?php esc_html_e('Choose your own amount','straysafe-ui-suite'); ?><input type="number" min="<?php echo esc_attr($s[$section]['min']); ?>" max="<?php echo esc_attr($s[$section]['max']); ?>" step="0.01" inputmode="decimal" /></label><?php endif; ?></div><?php endforeach; ?>
  <p class="ss-payments-impact" aria-live="polite"></p><p class="ss-payments-error" role="alert"></p><button type="button" class="ss-payments-continue" disabled><?php echo esc_html($s['general']['button_text']); ?></button>
</section><?php return ob_get_clean(); }
  private static function money($amount,$currency){ $symbol=['GBP'=>'£','USD'=>'$','EUR'=>'€'][$currency]??$currency.' '; return $symbol.rtrim(rtrim(number_format((float)$amount,2), '0'), '.'); }
  public static function render_admin_page() { if(!current_user_can('manage_options')) return; $s=self::settings(); $providers=self::gateway_manager()->all(); echo '<div class="wrap"><h1>Payments</h1><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">'; wp_nonce_field('straysafe_payments_save'); echo '<input type="hidden" name="action" value="straysafe_payments_save"/><h2>Payment Provider</h2>'; foreach($providers as $id=>$p){ echo '<label style="display:block;margin:8px 0"><input type="radio" name="payments[active_provider]" value="'.esc_attr($id).'" '.checked($s['active_provider'],$id,false).'/> '.esc_html($p->get_name()).'</label><div class="ssp-provider-fields" data-provider="'.esc_attr($id).'"><table class="form-table">'; $status=$p->validate_configuration($s['provider_settings'][$id]??[]); echo '<tr><th>Connection status</th><td><strong>'.esc_html($status['connected']?'Connected':'Needs configuration').'</strong><p>'.esc_html($status['message']).'</p></td></tr>'; foreach($p->get_configuration_fields() as $key=>$f){ $val=$s['provider_settings'][$id][$key]??''; echo '<tr><th>'.esc_html($f['label']).'</th><td>'; if($f['type']==='checkbox') echo '<input type="checkbox" name="payments[provider_settings]['.esc_attr($id).']['.esc_attr($key).']" value="1" '.checked($val,1,false).'/>'; else echo '<input class="regular-text" type="'.esc_attr($f['type']).'" name="payments[provider_settings]['.esc_attr($id).']['.esc_attr($key).']" value="'.esc_attr($val).'" autocomplete="off"/>'; echo '</td></tr>'; } echo '</table></div>'; } echo '<h2>General</h2><table class="form-table">'; foreach(['enabled'=>'Enable widget','enable_campaigns'=>'Enable campaigns'] as $k=>$label) echo '<tr><th>'.$label.'</th><td><input type="checkbox" name="payments[general]['.$k.']" value="1" '.checked($s['general'][$k],1,false).'/></td></tr>'; foreach(['title','subtitle','intro_text','currency','success_url','cancel_url','button_text','thank_you_message','learn_more_url'] as $k) echo '<tr><th>'.esc_html(ucwords(str_replace('_',' ',$k))).'</th><td><input class="regular-text" name="payments[general]['.esc_attr($k).']" value="'.esc_attr($s['general'][$k]).'"/></td></tr>'; echo '</table><h2>Amounts</h2>'; foreach(['one_off'=>'One-off Donations','recurring'=>'Recurring Donations'] as $section=>$label){ echo '<h3>'.esc_html($label).'</h3><table class="widefat"><thead><tr><th>Amount</th><th>Description</th><th>Icon</th><th>Colour</th><th>Campaign</th></tr></thead><tbody>'; $rows=array_pad($s[$section]['presets'],8,[]); foreach($rows as $i=>$r){ echo '<tr><td><input name="payments['.$section.'][presets]['.$i.'][amount]" value="'.esc_attr($r['amount']??'').'"/></td><td><input class="regular-text" name="payments['.$section.'][presets]['.$i.'][description]" value="'.esc_attr($r['description']??'').'"/></td><td><input name="payments['.$section.'][presets]['.$i.'][icon]" value="'.esc_attr($r['icon']??'').'"/></td><td><input type="color" name="payments['.$section.'][presets]['.$i.'][colour]" value="'.esc_attr($r['colour']??'#401268').'"/></td><td><input name="payments['.$section.'][presets]['.$i.'][campaign]" value="'.esc_attr($r['campaign']??'').'"/></td></tr>'; } echo '</tbody></table>'; foreach(['enabled','allow_custom'] as $k) echo '<label><input type="checkbox" name="payments['.$section.']['.$k.']" value="1" '.checked($s[$section][$k],1,false).'/> '.esc_html(ucwords(str_replace('_',' ',$k))).'</label> '; foreach(['min','max','default'] as $k) echo esc_html($k).' <input class="small-text" name="payments['.$section.']['.$k.']" value="'.esc_attr($s[$section][$k]).'"/> '; } echo '<h2>Appearance</h2><p>Live preview: '.do_shortcode('[donation_widget]').'</p>'; submit_button('Save Payments Settings'); echo '</form></div><script>document.querySelectorAll("input[name=\'payments[active_provider]\']").forEach(function(r){function u(){document.querySelectorAll(".ssp-provider-fields").forEach(function(e){e.style.display=e.dataset.provider===document.querySelector("input[name=\'payments[active_provider]\']:checked").value?"block":"none"})}r.addEventListener("change",u);u();});</script>'; }
}
StraySafe_Payments_Module::init();
